function adminLayout(title, body) { return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${css()}${adminCss()}</style></head><body><div class="admin-shell"><aside><a class="brand" href="/dashboard">YMI <span>CMS</span></a><a href="/dashboard">Overview</a><a href="/studio">Post AI Studio</a><a href="/homepage-builder">Homepage Builder</a><a href="/media-library">Media Library</a><a href="/seo-manager">SEO Manager</a><a href="/users">Users & Roles</a><a href="/" target="_blank">View Website</a><a href="/logout">Logout</a></aside><main>${body}</main></div></body></html>`; }
