app.get('/api/admin/homepage/:section', requireRole(['admin', 'editor']), async (req, res) => { const h = await loadHomepage(); res.json({ success: true, items: h[req.params.section] || [] }); });
app.post('/api/admin/homepage/:section', requireRole(['admin', 'editor']), (req, res) => { const s = req.params.section; if (!homepage[s]) return res.status(404).json({ success: false, message: 'Invalid section' }); const item = { id: Date.now(), ...req.body, is_active: Number(req.body.is_active ?? 1), sort_order: Number(req.body.sort_order || 0) }; homepage[s].push(item); res.json({ success: true, source: 'memory', item }); });
app.put('/api/admin/homepage/:section/:id', requireRole(['admin', 'editor']), (req, res) => { const s = req.params.section, id = Number(req.params.id); if (!homepage[s]) return res.status(404).json({ success: false, message: 'Invalid section' }); homepage[s] = homepage[s].map(x => Number(x.id) === id ? { ...x, ...req.body, id } : x); res.json({ success: true, source: 'memory' }); });
app.delete('/api/admin/homepage/:section/:id', requireRole(['admin', 'editor']), (req, res) => { const s = req.params.section, id = Number(req.params.id); if (homepage[s]) homepage[s] = homepage[s].filter(x => Number(x.id) !== id); res.json({ success: true, source: 'memory' }); });
app.get('/api/ai/status', requireRole(['admin', 'editor', 'author']), (req, res) => res.json({ success: true, openaiConfigured: !!process.env.OPENAI_API_KEY, model: process.env.OPENAI_MODEL || 'gpt-4o-mini', imageModel: process.env.OPENAI_IMAGE_MODEL || 'gpt-image-1' }));
app.post('/api/ai/post-assist', requireRole(['admin', 'editor', 'author']), async (req, res) => { const fallback = makePost(req.body.category, req.body.title, req.body.content || req.body.idea, req.body.language); if (!process.env.OPENAI_API_KEY) return res.json({ success: true, source: 'fallback-no-key', suggestion: fallback }); try { const r = await fetch('https://api.openai.com/v1/chat/completions', { method: 'POST', headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: process.env.OPENAI_MODEL || 'gpt-4o-mini', messages: [{ role: 'system', content: 'Return valid JSON only with title, category, excerpt, content, hashtags array, meta_title, meta_description, seo_keywords.' }, { role: 'user', content: `${req.body.mode === 'modify' ? 'Improve' : 'Create'} a global magazine blog for YE MERA INDIA. Category: ${req.body.category}. Title: ${req.body.title}. Language: ${req.body.language}. Idea/content: ${req.body.content || req.body.idea}` }], temperature: .75 }) }); const data = await r.json(); const text = data?.choices?.[0]?.message?.content || '{}'; res.json({ success: true, source: 'openai', suggestion: { ...fallback, ...JSON.parse(text.replace(/```json|```/g, '').trim()) } }); } catch (e) { res.json({ success: true, source: 'fallback-error', message: e.message, suggestion: fallback }); } });
app.post('/api/ai/seo', requireRole(['admin', 'editor', 'author']), (req, res) => { const title = req.body.title || 'Vivid India Story'; const cat = req.body.category || 'India'; res.json({ success: true, seo: { meta_title: `${title} | YE MERA INDIA`, meta_description: `${title} is a magazine-style story about ${cat}, Indian culture, travel, art and vivid storytelling.`, keywords: [cat, 'India', 'Vivid India', 'Indian culture', 'Author blog', 'India magazine'] } }); });
app.post('/api/ai/media-suggest', requireRole(['admin', 'editor', 'author', 'media_manager']), (req, res) => res.json({ success: true, suggestion: { style: 'Vibrant India editorial cover', prompt: `Create a warm Indian magazine visual for ${req.body.category || 'India'}: saffron, gold, green accents, cultural texture, clean blog cover, global audience friendly.`, caption: `A vivid editorial visual for ${req.body.title || 'the story'}.` } }));
app.post('/api/ai/image-generate', requireRole(['admin', 'editor', 'media_manager']), async (req, res) => { if (!process.env.OPENAI_API_KEY) return res.json({ success: false, configured: false, message: 'OPENAI_API_KEY missing. Use Studio AI prompt for manual design or add key to enable optional image generation.' }); res.json({ success: false, configured: true, message: 'Optional image generation endpoint prepared. Enable after confirming billing/model access.', prompt: req.body.prompt }); });
app.get('/api/analytics/summary', requireRole(['admin', 'editor']), async (req, res) => { const ps = await loadPosts(); res.json({ success: true, summary: { posts: ps.length, categories: categories.length, media: mediaAssets.length, roles: ROLES.length, events: analytics.length } }); });

app.use((req, _res, next) => { if (!req.path.startsWith('/api') && !req.path.startsWith('/uploads')) analytics.push({ path: req.path, at: Date.now() }); next(); });

app.get('/', async (req, res) => { const h = await loadHomepage(); const hero = activeSort(h.heroBanners)[0] || homepage.heroBanners[0]; const tiles = activeSort(h.tiles).slice(0, 8); const subs = activeSort(h.subHeroBanners).slice(0, 3); const gal = activeSort(h.mediaGallery).slice(0, 6); const latest = (await loadPosts()).slice(0, 6); res.type('html').send(publicLayout('YE MERA INDIA - Vivid India Magazine', `<section class="wrap hero"><div><span class="badge">${esc(hero.subtitle)}</span><h1>${esc(hero.title)}</h1><p class="lead">${esc(hero.description)}</p><a class="btn" href="${esc(hero.button1_link || '/posts')}">${esc(hero.button1_text || 'Read Magazine')}</a><a class="btn btn2" href="${esc(hero.button2_link || '/categories')}">${esc(hero.button2_text || 'Categories')}</a></div><div class="mandala"><div class="namaste"><div class="sign">🙏</div><b>नमस्ते</b><p>Welcome to Vivid India</p></div></div></section><div class="ribbon">नमस्ते • Vivid India • Global Magazine • Author Blog • Artist Portfolio • Full CMS</div><section class="wrap"><span class="badge">Editor Picks</span><div class="grid">${subs.map(x => `<div class="card"><h3>${esc(x.title)}</h3><p>${esc(x.short_text)}</p><a class="btn btn2" href="${esc(x.button_link || '/posts')}">${esc(x.button_text || 'Open')}</a></div>`).join('')}</div></section><section class="wrap"><span class="badge">Categories</span><h2>Explore vibrant India</h2><div class="grid">${tiles.map(x => `<div class="card" style="background:${esc(x.bg_color || '#170805')}"><div class="tile-icon">${esc(x.icon_name || '✨')}</div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><a class="btn btn2" href="${esc(x.button_link || '/posts')}">${esc(x.button_text || 'Open')}</a></div>`).join('')}</div></section><section class="wrap"><span class="badge">Latest Stories</span><h2>Magazine posts</h2><div class="grid">${latest.map(pageCard).join('')}</div></section><section id="gallery" class="wrap"><span class="badge">Media Gallery</span><h2>India in pictures</h2><div class="grid">${gal.length ? gal.map(x => `<div class="card">${x.file_url ? `<img class="thumb" src="${x.file_url}">` : ''}<h3>${esc(x.title)}</h3><p>${esc(x.caption)}</p></div>`).join('') : '<div class="card"><h3>Upload media from CMS</h3><p>Use Media Library and Homepage Builder to publish a visual gallery.</p></div>'}</div></section>`)); });
