app.get('/login', (_req, res) => res.type('html').send(publicLayout('Login', `<section class="wrap"><div class="card" style="max-width:520px;margin:auto"><span class="badge">CMS Login</span><h1>Dashboard Access</h1><input id="email" type="email" placeholder="Admin email"><input id="password" type="password" placeholder="Password"><button onclick="login()">Sign In</button><p id="msg" class="small"></p></div></section><script>async function login(){msg.textContent='Checking...';let d=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})}).then(r=>r.json());if(d.success)location.href='/dashboard';else{msg.className='error';msg.textContent=d.message||'Login failed'}}</script>`)));
