app.get('/studio', requirePage(['admin', 'editor', 'author']), (_req, res) => res.type('html').send(adminLayout('Post AI Studio', `<div class="topbar"><span class="badge">Post AI + Studio AI</span><button onclick="seedBlogs()">Create Blogs For Every Category</button><button class="ghost" onclick="aiStatus()">Check AI Status</button><a class="btn btn2" href="/posts" target="_blank">View Posts</a></div><div class="two"><div class="card manager"><h2>Post Manager</h2><button onclick="newPost()">New Post</button><button class="ghost" onclick="loadPosts()">Refresh</button><div id="postList"></div></div><div class="card"><h2>Create / Modify Current Post</h2><input id="postId" type="hidden"><select id="category">${categories.map(c => `<option>${c.name}</option>`).join('')}</select><select id="language"><option value="en">English</option><option value="hi">Hindi</option><option value="en-hi">English + Hindi</option></select><input id="title" placeholder="Title"><textarea id="idea" placeholder="Idea/current news/source notes. AI will create original post."></textarea><button onclick="postAi('create')">Post AI Create</button><button class="ghost" onclick="postAi('modify')">Post AI Modify</button><button class="ghost" onclick="seoAi()">SEO AI</button><input id="excerpt" placeholder="Excerpt"><textarea id="content" placeholder="Full post content"></textarea><input id="hashtags" placeholder="#VividIndia #India"><h3>Cover Media</h3><input type="file" id="photo" accept="image/*"><button onclick="uploadCover()">Upload Cover To Server</button><button onclick="mediaIdea()">Studio AI Media Idea</button><button onclick="mediaPreset('vivid')">AI Vivid</button><button onclick="mediaPreset('heritage')">AI Heritage</button><label>Brightness</label><input type="range" id="b" min="0.4" max="2" step="0.1" value="1"><label>Contrast</label><input type="range" id="c" min="0.4" max="2" step="0.1" value="1"><label>Saturation</label><input type="range" id="s" min="0" max="2.5" step="0.1" value="1"><label>Warmth</label><input type="range" id="sep" min="0" max="0.8" step="0.1" value="0"><img id="preview" class="preview"><input id="cover_image" placeholder="Cover image URL"><button onclick="savePost()">Save / Update Post</button><button class="danger" onclick="deleteCurrent()">Delete Current</button><p id="msg" class="small"></p></div></div><script>${studioScript()}</script>`)));
app.get('/homepage-builder', requirePage(['admin', 'editor']), (_req, res) => res.type('html').send(adminLayout('Homepage Builder', `<div class="topbar"><span class="badge">Professional Website Builder</span><button onclick="openTab('heroBanners')">Hero</button><button onclick="openTab('subHeroBanners')">Sub Hero</button><button onclick="openTab('mediaGallery')">Gallery</button><button onclick="openTab('tiles')">Tiles</button><a class="btn btn2" href="/" target="_blank">Preview Website</a></div><div class="two"><div class="card manager"><h2 id="listTitle">Items</h2><div id="builderList"></div></div><div class="card"><h2>Add / Edit Section</h2><input id="itemId" type="hidden"><input id="title" placeholder="Title"><input id="subtitle" placeholder="Subtitle / short text / category"><textarea id="description" placeholder="Description / caption"></textarea><input id="btn1" placeholder="Button text"><input id="link1" placeholder="Button link"><input id="icon" placeholder="Icon emoji"><input id="bg" placeholder="Background color"><input id="sort" type="number" value="0"><select id="active"><option value="1">Active</option><option value="0">Inactive</option></select><input type="file" id="file" accept="image/*"><img id="imagePreview" class="thumb"><button onclick="saveItem()">Save Section</button><button class="ghost" onclick="newItem()">New</button><button class="danger" onclick="deleteItem()">Delete</button><p id="bmsg" class="small"></p></div></div><script>${builderScript()}</script>`)));
app.get('/media-library', requirePage(['admin', 'editor', 'author', 'media_manager']), (_req, res) => res.type('html').send(adminLayout('Media Library', `<span class="badge">Server Uploads</span><h1>Media Library</h1><div class="two"><div class="card"><input id="mtitle" placeholder="Media title"><input id="mcategory" placeholder="Category"><textarea id="mcaption" placeholder="Caption / alt text"></textarea><input type="file" id="mfile" accept="image/*"><button onclick="uploadMedia()">Upload Media</button><p id="mmsg" class="small"></p></div><div class="card manager"><h2>Assets</h2><div id="assets"></div></div></div><script>let dataUrl='';mfile.onchange=e=>{let f=e.target.files[0];let r=new FileReader();r.onload=()=>dataUrl=r.result;if(f)r.readAsDataURL(f)};async function uploadMedia(){let d=await fetch('/api/admin/media/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl,title:mtitle.value,category:mcategory.value,caption:mcaption.value,alt_text:mcaption.value})}).then(r=>r.json());mmsg.className=d.success?'success':'error';mmsg.textContent=d.success?'Uploaded: '+d.url:d.message;loadAssets()}async function loadAssets(){let d=await fetch('/api/admin/media').then(r=>r.json());assets.innerHTML=(d.assets||[]).map(a=>'<div class="item"><img class="thumb" src="'+a.file_url+'"><h3>'+a.title+'</h3><p>'+a.file_url+'</p></div>').join('')||'No media yet'}loadAssets()</script>`)));
app.get('/seo-manager', requirePage(['admin', 'editor', 'author']), (_req, res) => res.type('html').send(adminLayout('SEO Manager', `<span class="badge">SEO AI</span><h1>SEO Manager</h1><div class="card"><input id="stitle" placeholder="Post/page title"><input id="scat" placeholder="Category"><button onclick="genSeo()">Generate SEO</button><pre id="seoOut" class="card"></pre></div><script>async function genSeo(){let d=await fetch('/api/ai/seo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:stitle.value,category:scat.value})}).then(r=>r.json());seoOut.textContent=JSON.stringify(d.seo,null,2)}</script>`)));
app.get('/users', requirePage(['admin']), (_req, res) => res.type('html').send(adminLayout('Users & Roles', `<span class="badge">Roles</span><h1>Users & Roles</h1><div class="grid">${ROLES.map(r => `<div class="card"><h3>${r}</h3><p>Role-based CMS access enabled.</p></div>`).join('')}</div><div class="card"><h2>Current Users</h2>${users.map(u => `<p>${esc(u.name)} — ${esc(u.email)} — <b>${esc(u.role)}</b></p>`).join('')}</div>`)));

function studioScript() { return `const qs=x=>document.getElementById(x);let allPosts=[],cover='';function safe(v){return String(v||'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}function localGen(){let c=category.value,t=title.value||c+' Story',i=idea.value||content.value||t;return{title:t,category:c,excerpt:t+' connects audience interest with India’s culture and global identity.',content:t+'\n\n'+i+' is a strong magazine story because it explains the topic with context, colour and human emotion.\n\nIndia is vivid because local moments carry national memory. This story connects people, place, culture and modern attention in a simple global style.\n\nहिंदी भाव: यह कहानी भारत की संस्कृति, रंग और पहचान को सरल भाषा में सामने लाती है।',hashtags:['#India','#VividIndia','#IndianCulture','#Magazine']}}function fill(x,source){title.value=x.title||title.value;category.value=x.category||category.value;excerpt.value=x.excerpt||'';content.value=x.content||'';hashtags.value=Array.isArray(x.hashtags)?x.hashtags.join(' '):(x.hashtags||hashtags.value);msg.className='success';msg.textContent='Generated using '+source+'. Review and save.'}async function postAi(mode){msg.className='small';msg.textContent='Generating...';try{let d=await fetch('/api/ai/post-assist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,category:category.value,title:title.value,content:content.value||idea.value,language:language.value})}).then(r=>r.json());fill(d.suggestion||localGen(),d.source||'api')}catch(e){fill(localGen(),'browser-fallback')}}async function seoAi(){let d=await fetch('/api/ai/seo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.value,category:category.value})}).then(r=>r.json());msg.className='success';msg.textContent='SEO: '+d.seo.meta_title+' | '+d.seo.keywords.join(', ')}async function aiStatus(){let d=await fetch('/api/ai/status').then(r=>r.json());msg.className=d.openaiConfigured?'success':'error';msg.textContent=d.openaiConfigured?'OpenAI configured: '+d.model:'OpenAI key missing. Fallback will still generate content.'}async function loadPosts(){postList.innerHTML='Loading...';let d=await fetch('/api/admin/posts').then(r=>r.json());allPosts=d.posts||[];postList.innerHTML=allPosts.map(p=>'<div class="item"><h3>'+safe(p.title)+'</h3><p class="small">'+safe(p.category)+'</p><button onclick="editPost('+p.id+')">Edit</button><button class="danger" onclick="deletePost('+p.id+')">Delete</button></div>').join('')||'No posts yet'}function newPost(){postId.value='';title.value='';idea.value='';excerpt.value='';content.value='';hashtags.value='';cover_image.value='';cover=''}function editPost(id){let p=allPosts.find(x=>Number(x.id)===Number(id));if(!p)return;postId.value=p.id;category.value=p.category||'Viral India';language.value=p.language||'en';title.value=p.title||'';excerpt.value=p.excerpt||'';content.value=(p.content||'').replace(/\n\n#.*$/s,'');hashtags.value=((p.content||'').match(/#\w+/g)||[]).join(' ');cover_image.value=p.cover_image||''}async function savePost(){let id=postId.value;let body={title:title.value,category:category.value,language:language.value,excerpt:excerpt.value,content:content.value,hashtags:hashtags.value,cover_image:cover_image.value};let d=await fetch(id?'/api/posts/'+id:'/api/posts',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json());msg.className='success';msg.textContent='Saved using '+d.source;await loadPosts()}async function deleteCurrent(){if(postId.value)await deletePost(postId.value)}async function deletePost(id){if(!confirm('Delete post?'))return;await fetch('/api/posts/'+id,{method:'DELETE'});await loadPosts()}async function seedBlogs(){let d=await fetch('/api/admin/seed-category-blogs',{method:'POST'}).then(r=>r.json());msg.className='success';msg.textContent='Created '+d.created+' category blogs';await loadPosts()}function apply(){preview.style.setProperty('--b',b.value);preview.style.setProperty('--c',c.value);preview.style.setProperty('--s',s.value);preview.style.setProperty('--sep',sep.value)}['b','c','s','sep'].forEach(id=>qs(id).oninput=apply);photo.onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{cover=r.result;preview.src=cover;apply()};r.readAsDataURL(f)};function mediaPreset(n){let v=n==='heritage'?[1.08,1.15,1.2,.45]:[1.15,1.25,1.6,.1];b.value=v[0];c.value=v[1];s.value=v[2];sep.value=v[3];apply();msg.className='success';msg.textContent='Studio AI media preset applied.'}async function uploadCover(){if(!cover)return alert('Choose image first');let d=await fetch('/api/admin/media/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl:cover,title:title.value||'cover',category:category.value,caption:excerpt.value})}).then(r=>r.json());if(d.success){cover_image.value=d.url;msg.className='success';msg.textContent='Cover uploaded: '+d.url}else{msg.className='error';msg.textContent=d.message}}async function mediaIdea(){let d=await fetch('/api/ai/media-suggest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:category.value,title:title.value})}).then(r=>r.json());msg.className='success';msg.textContent=d.suggestion.prompt}loadPosts();`; }
function builderScript() { return `let section='heroBanners',items=[],media='';function qs(x){return document.getElementById(x)}function safe(v){return String(v||'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}function openTab(s){section=s;newItem();load()}file.onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{media=r.result;imagePreview.src=media};r.readAsDataURL(f)}async function load(){let d=await fetch('/api/admin/homepage/'+section).then(r=>r.json());items=d.items||[];listTitle.textContent={heroBanners:'Hero Banner',subHeroBanners:'Sub Hero',mediaGallery:'Media Gallery',tiles:'Tiles Block'}[section];builderList.innerHTML=items.map(x=>'<div class="item"><h3>'+safe(x.title)+'</h3>'+((x.image_url||x.file_url)?'<img class="thumb" src="'+(x.image_url||x.file_url)+'">':'')+'<p class="small">Order '+(x.sort_order||0)+'</p><button onclick="edit('+x.id+')">Edit</button></div>').join('')||'<p>No items yet.</p>'}function newItem(){itemId.value='';title.value='';subtitle.value='';description.value='';btn1.value='';link1.value='';icon.value='';bg.value='';sort.value='0';active.value='1';media='';imagePreview.src=''}function edit(id){let x=items.find(i=>Number(i.id)===Number(id));if(!x)return;itemId.value=x.id;title.value=x.title||'';subtitle.value=x.subtitle||x.short_text||x.category||'';description.value=x.description||x.caption||'';btn1.value=x.button1_text||x.button_text||'';link1.value=x.button1_link||x.button_link||'';icon.value=x.icon_name||'';bg.value=x.bg_color||'';sort.value=x.sort_order||0;active.value=Number(x.is_active)!==0?'1':'0';media=x.image_url||x.file_url||'';imagePreview.src=media}function payload(){let p={title:title.value,sort_order:Number(sort.value||0),is_active:Number(active.value)};if(section==='heroBanners')Object.assign(p,{subtitle:subtitle.value,description:description.value,button1_text:btn1.value,button1_link:link1.value,button2_text:'Categories',button2_link:'/categories',image_url:media});else if(section==='subHeroBanners')Object.assign(p,{short_text:subtitle.value,image_url:media,button_text:btn1.value,button_link:link1.value});else if(section==='mediaGallery')Object.assign(p,{media_type:'image',caption:description.value,file_url:media,category:subtitle.value,is_featured:1});else Object.assign(p,{description:description.value,image_url:media,icon_name:icon.value,bg_color:bg.value||'#170805',button_text:btn1.value,button_link:link1.value,tile_size:'medium'});return p}async function saveItem(){let id=itemId.value;let d=await fetch(id?'/api/admin/homepage/'+section+'/'+id:'/api/admin/homepage/'+section,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())}).then(r=>r.json());bmsg.className='success';bmsg.textContent='Saved using '+d.source;await load()}async function deleteItem(){if(!itemId.value)return alert('Select item first');await fetch('/api/admin/homepage/'+section+'/'+itemId.value,{method:'DELETE'});newItem();await load()}load();`; }

